// Offline service worker. Generated by scripts/build.py: __VERSION__ and __FILES__ are filled in at build time.
const VERSION = '__VERSION__';
const FILES = __FILES__;
const CACHE = 'karnak-' + VERSION;
const TOTAL = FILES.reduce((s, f) => s + f.bytes, 0);

async function tell(msg) {
  const clients = await self.clients.matchAll({ includeUncontrolled: true });
  clients.forEach(c => c.postMessage(msg));
}

// Download everything into a new cache. The old cache stays in use until this finishes,
// so an interrupted update never breaks the working guide.
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    let done = 0, n = 0;
    const queue = FILES.slice();
    const worker = async () => {
      while (queue.length) {
        const f = queue.shift();
        if (!(await cache.match(f.url))) {
          const res = await fetch(f.url, { cache: 'reload' });
          if (!res.ok) throw new Error('Failed ' + f.url);
          await cache.put(f.url, res);
        }
        done += f.bytes; n++;
        if (n % 10 === 0 || !queue.length) tell({ type: 'progress', done, total: TOTAL, version: VERSION });
      }
    };
    await Promise.all([worker(), worker(), worker(), worker()]);
    await cache.put('__complete__', new Response(VERSION));
    await tell({ type: 'ready', version: VERSION, total: TOTAL });
    self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('karnak-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  if (event.data === 'status') {
    caches.open(CACHE).then(c => c.match('__complete__')).then(r =>
      event.source.postMessage({ type: r ? 'ready' : 'pending', version: VERSION, total: TOTAL }));
  }
});

// Safari asks for videos in byte ranges; answer from the cached file.
async function rangeResponse(req, res) {
  const buf = await res.arrayBuffer();
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.get('range') || '');
  const size = buf.byteLength;
  let start = m && m[1] ? +m[1] : 0, end = m && m[2] ? +m[2] : size - 1;
  if (m && !m[1] && m[2]) { start = size - +m[2]; end = size - 1; }
  end = Math.min(end, size - 1);
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    headers: { 'Content-Type': res.headers.get('Content-Type') || 'video/mp4', 'Content-Range': `bytes ${start}-${end}/${size}`, 'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' }
  });
}

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return; // source links etc. need the internet, as expected
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // Pages (incl. ?lang=uk) all open the same app shell.
    if (req.mode === 'navigate') {
      return (await cache.match('index.html')) || fetch(req);
    }
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return req.headers.has('range') ? rangeResponse(req, hit) : hit;
    try { return await fetch(req); }
    catch { return new Response('', { status: 504, statusText: 'Offline' }); }
  })());
});
